public Qty parmQuantity(Qty _qty = qty)
{
    qty = _qty;
    if (qty == 0 && serialId)
    {
        qty = InventSum::find(itemId, this.createInventDim(inventDim).inventDimId).AvailPhysical;
    }
    return qty;
}

public Qty parmQuantityRemaining(Qty _qty = qty)
{
    return this.parmQuantity(_qty);
}

